class SymbolDF(pd.DataFrame):
    def _getitem_column(self, symbol):
        try:
            return super(SymbolDF, self)._getitem_column(symbol)
            return None
        except (AttributeError, KeyError):
            system_log.error('异常信息: %s' % get_traceback_message())
        try:
            symbol = endswith_transe_2to4(symbol)
            return super(SymbolDF, self)._getitem_column(symbol)
            return None
        except (AttributeError, KeyError):
            system_log.error('异常信息: %s' % get_traceback_message())
        try:
            symbol = symbol.replace('XSHG', 'SS').replace('XSHE', 'SZ')
            return super(SymbolDF, self)._getitem_column(symbol)
            return None
        except (AttributeError, KeyError):
            system_log.error('异常信息: %s' % get_traceback_message())
            raise KeyError(symbol)
def execute_with_live_output(cmd, log):
    """
    执行命令实时记录日志函数
    :param cmd: 待执行命令
    :type cmd: str
    :param log: 记录日志方法
    :type log: object
    :return: 命令执行是否异常
    :rtype: bool
    """
    execute_error = False
    process = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    for line in iter(process.stdout.readline, b''):
        try:
            line_info = line.decode('utf-8', errors='ignore').strip()
            log.info(line_info)
            if 'ERROR' in line_info or 'AssertionError' in line_info:
                execute_error = True
        except BaseException:
            log.error('Error decoding line: %s' % line)
    else:
        process.wait()
        return execute_error
def not_none_string(parameter_str: str) -> bool:
    """
    判断字符串参数是否为None，去除前后空格换行符后是否为“”

    参数:
    parameter_str: str, 字符串入参

    返回:
    bool, 为空返回False，否则返回True
    """
    if parameter_str is None or parameter_str.strip() == '':
        return False
    else:
        return True
def get_crontab_execute_time(crontab_file_path, task_name):
    try:
        lines = FileIO(crontab_file_path, file_format='txt').read(return_type='line_reader')
        if len(lines) <= 0:
            error_message = '任务名称:%s的定时任务运行时间获取失败,错误原因:定时任务文件内容为空' % task_name
            system_log.error(error_message)
            return (None, None)
        else:
            for line in lines:
                line_info = line.split("',")
                script_time_info = line_info[0]
                if task_name in script_time_info:
                    split_info = script_time_info.split()
                    minute_info = split_info[0]
                    hour_info = split_info[1]
                    return (hour_info, minute_info)
            else:
                return (None, None)
    except BaseException:
        error_message = f'任务名称:{task_name!s}的定时任务运行时间获取失败,错误原因{get_traceback_message()!s}'
        system_log.error(error_message)
        return (None, None)
def set_pdeathsig():
    """
    设置子进程在父进程终止时接收到的信号(Linux)。
    该函数使用 prctl 系统调用，设置子进程在父进程终止时会接收到 SIGTERM 信号。
    这可以确保子进程在父进程意外终止时，也能够优雅地处理并终止。
    """
    libc = ctypes.CDLL('libc.so.6')
    PR_SET_PDEATHSIG = 1
    signal_to_send = signal.SIGTERM
    libc.prctl(PR_SET_PDEATHSIG, signal_to_send)
def backup_user_list_file(ip_list, target_path):
    """
    备份用户列表文件
    :param ip_list: 服务器IP列表
    :type ip_list: list
    :param target_path: 备份路径
    :type target_path: str
    """
    os.makedirs(target_path, exist_ok=True)
    for ip in ip_list:
        try:
            docker_usernames_path = os.path.join(NOTEBOOK_DIR_PATH, 'backup_users', 'docker_usernames_{}.txt'.format(ip))
            if not os.path.exists(docker_usernames_path):
                system_log.warning('服务器{}用户列表文件不存在'.format(ip))
                continue
            backup_file_path = os.path.join(target_path, 'docker_usernames_{}.txt'.format(ip))
            if not os.path.exists(backup_file_path):
                shutil.copy2(docker_usernames_path, backup_file_path)
            system_log.info('备份服务器{}用户信息成功'.format(ip))
        except BaseException:
            system_log.error('备份服务器{}用户信息失败，错误原因：{}'.format(ip, get_traceback_message()))
